function make(key: string) {
  const { viewBox, body } = G[key];
  const C = (props: SVGProps<SVGSVGElement>) => (
    <svg
      width="24"
      height="24"
      viewBox={viewBox}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      focusable="false"
      {...props}
      dangerouslySetInnerHTML={{ __html: body }}
    />
  );
  C.displayName = "Figma" + key;
  return memo(C);
}

